import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百七十三章 无法永远存在","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/273第二百七十三章 无法永远存在.md","filePath":"meditation/巴利文大藏经/273第二百七十三章 无法永远存在.md"}'),r={name:"meditation/巴利文大藏经/273第二百七十三章 无法永远存在.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百七十三章-无法永远存在" tabindex="-1">第二百七十三章 无法永远存在 <a class="header-anchor" href="#第二百七十三章-无法永远存在" aria-label="Permalink to &quot;第二百七十三章 无法永远存在&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应66经/无常经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，一位比丘（出家人），来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，这位比丘对佛陀说：“世尊，请您教导给我一个简要的修行方法，让我独自修行的时候，能够管束好自己的行为、言语、念想，让我不放逸自己的行为、言语、念想肆意妄为、胡作非为，让我不胡思乱想，能长久的安住在清净的境界之中，让我能够精进努力的去修行，世尊，如果您教导给我的正法能够让我这样的话，那就很好了。”</p><p>佛陀说：“比丘！对于那些随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的事物，你都不应该生起欲望、渴爱，你应该除灭这些欲望、渴爱。”</p><p>这位比丘对佛陀说：“世尊，我已经明白您所说的法义了。”</p><p>佛陀说：“比丘！你既然明白了如来所说的法义，那么你现在就在如来面前详细的讲说这个法义吧。”</p><p>这位比丘说：“世尊，物质事物、物质身体、感受、念想、行为、认识、分别、判断是随时在变化的，是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的，物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的。感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的。因此不应该对它们生起欲望、渴爱，应该除灭对它们的欲望、渴爱。”</p><p>佛陀说：“比丘！很好！很好！你已经完全明白如来刚才所说的法义了，你就应该这样去修行。”</p><p>佛陀说法后，这位出家人再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他站起来向右围绕着佛陀转圈，以此表示他对佛陀的最高敬意，之后他就离开了。</p><p>这位出家人，他按着佛陀所说的正法独自的去修行，他管束好了自己的行为、言语、念想，不让自己胡思乱想、胡作非为，他让自己的内心安住在清净的境界之中，没有过多久，这位出家人他就开启了解脱的智慧，他就证悟了解脱的果位，他自己彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」</p><p>这位出家人成为了佛陀阿罗汉弟子中的一员。</p>',12)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
